size_t fwrite(const void*деректер_лауазым,size_t жол_деректер,size_t 개수,FILE*файл_енгізу){if(!жол_деректер)return 0;if(개수>SIZE_MAX/жол_деректер){файл_енгізу->Қате=1;return 0;}long 반환값=write(файл_енгізу->файл_дескриптор,деректер_лауазым,жол_деректер*개수);if(반환값<0){файл_енгізу->Қате=1;return 0;}return (size_t)반환값/жол_деректер;}
